      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0LD_1LC1RA_0RD0LC_1RA1RD j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LD_1LC1RA_0RD0LC_1RA1RD : forall t, ~ In t pins_1RB0LD_1LC1RA_0RD0LC_1RA1RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0LD_1LC1RA_0RD0LC_1RA1RD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RA_0RD0LC_1RA1RD [SRotL 1; SWin 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_1LC1RA_0RD0LC_1RA1RD (StA, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_1LC1RA_0RD0LC_1RA1RD [SRotL 1; SWin 1; SCycL 2 0; SWin 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RA_0RD0LC_1RA1RD [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_1LC1RA_0RD0LC_1RA1RD (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_1LC1RA_0RD0LC_1RA1RD [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RA_0RD0LC_1RA1RD [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RA_0RD0LC_1RA1RD [SRotL 1; SWin 1; SCycL 2 0; SWin 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RA_0RD0LC_1RA1RD [] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_1LC1RA_0RD0LC_1RA1RD (StD, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_1LC1RA_0RD0LC_1RA1RD [SRotL 1; SWin 1; SCycL 2 0; SWin 3] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtrm_1RB0LD_1LC1RA_0RD0LC_1RA1RD : NeverQuasiHaltsTr tmm_1RB0LD_1LC1RA_0RD0LC_1RA1RD.
