Lemma gei_1RB0LD_1LC1RA_1LB1RC_0RA1LD : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Jp q0 ++ [S0]) [] j A1_1RB0LD_1LC1RA_1LB1RC_0RA1LD) = lift (Cc (Pos.succ p)).
