Lemma gsn_1RB0LD_1LC1RA_1LD1RC_0RA1LD : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Jp q0 ++ []) [] i AI0_1RB0LD_1LC1RA_1LD1RC_0RA1LD.
Proof.
  intros v i q0 E. destruct (JpCounter.cview_some_J v i q0 E) as (H1 & _).
  unfold Cin_1RB0LD_1LC1RA_1LD1RC_0RA1LD, cden, AI0_1RB0LD_1LC1RA_1LD1RC_0RA1LD; cbn [c_st c_l c_h c_r].
