Lemma geo_1RB0LD_1LC1RA_1RA1LC_0RB1LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LD_1LC1RA_1RA1LC_0RB1LD) = lift (Cc (Pos.succ p)).
