    apply (lap_of_run tm Cc true true cho_1RB0LD_1LC1RA_1RD0RA_0RB1LD B0_1RB0LD_1LC1RA_1RD0RA_0RB1LD B1_1RB0LD_1LC1RA_1RD0RA_0RB1LD 4 12 p j' [] []).
    + exact run_ovf_1RB0LD_1LC1RA_1RD0RA_0RB1LD.
    + reflexivity.
