  exists (4 * i + 8), (cden (Jp q0 ++ []) [] i AI1_1RB0LD_1LC1RA_1RD1LC_0RA1LD).
  split; [lia|]. split; [| exact (gen_1RB0LD_1LC1RA_1RD1LC_0RA1LD v i q0 E)].
  rewrite (gsn_1RB0LD_1LC1RA_1RD1LC_0RA1LD v i q0 E).
  exact (srun_sound tm false true chn_1RB0LD_1LC1RA_1RD1LC_0RA1LD AI0_1RB0LD_1LC1RA_1RD1LC_0RA1LD AI1_1RB0LD_1LC1RA_1RD1LC_0RA1LD 4 8
           run_inner_1RB0LD_1LC1RA_1RD1LC_0RA1LD (Jp q0 ++ []) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 2/1
    trailing blanks. *)
Lemma gbo_1RB0LD_1LC1RA_1RD1LC_0RA1LD : forall j, lift (cden [] [] j BB1_1RB0LD_1LC1RA_1RD1LC_0RA1LD) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LD_1LC1RA_1RD1LC_0RA1LD = (StA, (((rep [S1;S1] j ++ [S1]) ++ [S0]) ++ [S0], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB0LD_1LC1RA_1RD1LC_0RA1LD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S1] j ++ [S1], S0, []))).
  { unfold Cin_1RB0LD_1LC1RA_1RD1LC_0RA1LD. rewrite epow2_1RB0LD_1LC1RA_1RD1LC_0RA1LD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LD_1LC1RA_1RD1LC_0RA1LD. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0LD_1LC1RA_1RD1LC_0RA1LD : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB0LD_1LC1RA_1RD1LC_0RA1LD.
Proof.
  intro j.
  destruct (JpCounter.cview_none_J (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0LD_1LC1RA_1RD1LC_0RA1LD, cden, BE0_1RB0LD_1LC1RA_1RD1LC_0RA1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB0LD_1LC1RA_1RD1LC_0RA1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB0LD_1LC1RA_1RD1LC_0RA1LD. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LD_1LC1RA_1RD1LC_0RA1LD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LD_1LC1RA_1RD1LC_0RA1LD p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB0LD_1LC1RA_1RD1LC_0RA1LD).
    split; [lia|]. split; [| exact (gbo_1RB0LD_1LC1RA_1RD1LC_0RA1LD j)].
    rewrite (gso_1RB0LD_1LC1RA_1RD1LC_0RA1LD p j E).
    exact (srun_sound tm true true chb_1RB0LD_1LC1RA_1RD1LC_0RA1LD B0_1RB0LD_1LC1RA_1RD1LC_0RA1LD BB1_1RB0LD_1LC1RA_1RD1LC_0RA1LD 4 8
             run_boot_1RB0LD_1LC1RA_1RD1LC_0RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 13), (cden [] [] j B1_1RB0LD_1LC1RA_1RD1LC_0RA1LD).
    split; [| exact (geo_1RB0LD_1LC1RA_1RD1LC_0RA1LD p j E)].
    rewrite (gxi_1RB0LD_1LC1RA_1RD1LC_0RA1LD j).
    exact (srun_sound tm true true che_1RB0LD_1LC1RA_1RD1LC_0RA1LD BE0_1RB0LD_1LC1RA_1RD1LC_0RA1LD B1_1RB0LD_1LC1RA_1RD1LC_0RA1LD 4 13
             run_exit_1RB0LD_1LC1RA_1RD1LC_0RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
