    exact (srun_sound tm true true chb_1RB0LD_1LC1RA_1RD1LC_0RA1LD B0_1RB0LD_1LC1RA_1RD1LC_0RA1LD BB1_1RB0LD_1LC1RA_1RD1LC_0RA1LD 4 8
             run_boot_1RB0LD_1LC1RA_1RD1LC_0RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
