Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0LD_1LC1RA_1RD1LC_0RA1LD t p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB0LD_1LC1RA_1RD1LC_0RA1LD). split;
      [| exact (gbo_1RB0LD_1LC1RA_1RD1LC_0RA1LD j)].
