(** The chain into this family lands on its anchor up to 2/0
    trailing blanks. *)
Lemma gbo_1RB0LD_1LC1RA_1RD1LC_0RB1LD : forall j, lift (cden [] [] j BB1_1RB0LD_1LC1RA_1RD1LC_0RB1LD) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LD_1LC1RA_1RD1LC_0RB1LD = (StD, (((rep [S1;S1] j ++ [S1]) ++ [S0]) ++ [S0], S0, []))).
  { unfold cden, BB1_1RB0LD_1LC1RA_1RD1LC_0RB1LD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StD, (rep [S1;S1] j ++ [S1], S0, []))).
  { unfold Cin_1RB0LD_1LC1RA_1RD1LC_0RB1LD. rewrite epow2_1RB0LD_1LC1RA_1RD1LC_0RB1LD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LD_1LC1RA_1RD1LC_0RB1LD. rewrite ?lift_app_blank. reflexivity.
