Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LD_1LC1RB_0RB1LA_0RC1LA p (pow2 j)).
  - exists (4 * j + 17), (cden [] [] j BB1_1RB0LD_1LC1RB_0RB1LA_0RC1LA).
    split; [lia|]. split; [| exact (gbo_1RB0LD_1LC1RB_0RB1LA_0RC1LA j)].
    rewrite (gso_1RB0LD_1LC1RB_0RB1LA_0RC1LA p j E).
    exact (srun_sound tm true true chb_1RB0LD_1LC1RB_0RB1LA_0RC1LA B0_1RB0LD_1LC1RB_0RB1LA_0RC1LA BB1_1RB0LD_1LC1RB_0RB1LA_0RC1LA 4 17
             run_boot_1RB0LD_1LC1RB_0RB1LA_0RC1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 15), (cden [] [] j B1_1RB0LD_1LC1RB_0RB1LA_0RC1LA).
    split; [| exact (geo_1RB0LD_1LC1RB_0RB1LA_0RC1LA p j E)].
    rewrite (gxi_1RB0LD_1LC1RB_0RB1LA_0RC1LA j).
    exact (srun_sound tm true true che_1RB0LD_1LC1RB_0RB1LA_0RC1LA BE0_1RB0LD_1LC1RB_0RB1LA_0RC1LA B1_1RB0LD_1LC1RB_0RB1LA_0RC1LA 4 15
             run_exit_1RB0LD_1LC1RB_0RB1LA_0RC1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0LD_1LC1RB_0RB1LA_0RC1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LD_1LC1RB_0RB1LA_0RC1LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LD_1LC1RB_0RB1LA_0RC1LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LD_1LC1RB_0RB1LA_0RC1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 12.
  assert (H : match csteps tm 12 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 12 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LD_1LC1RB_0RB1LA_0RC1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LD_1LC1RB_0RB1LA_0RC1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LD_1LC1RB_0RB1LA_0RC1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LD_1LC1RB_0RB1LA_0RC1LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LD_1LC1RB_0RB1LA_0RC1LA : forall t, ~ In t pins_1RB0LD_1LC1RB_0RB1LA_0RC1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0LD_1LC1RB_0RB1LA_0RC1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RB_0RB1LA_0RC1LA [SWin 2; SWinR 4; SCycL 2 0; SWin 6; SCycR 2; SWin 4; SRotL 1; SWin 1; SWin 2] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RB_0RB1LA_0RC1LA [SWin 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RB_0RB1LA_0RC1LA [] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RB_0RB1LA_0RC1LA [SWin 2; SWinR 3] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RB_0RB1LA_0RC1LA [SWin 2; SWinR 2] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RB_0RB1LA_0RC1LA [SWin 1] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RB_0RB1LA_0RC1LA [SWin 2; SWinR 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RB_0RB1LA_0RC1LA [SWin 2; SWinR 4; SCycL 2 0; SWin 6] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtrm_1RB0LD_1LC1RB_0RB1LA_0RC1LA : NeverQuasiHaltsTr tmm_1RB0LD_1LC1RB_0RB1LA_0RC1LA.
Proof.
  apply (glue_neverqhtr tmm_1RB0LD_1LC1RB_0RB1LA_0RC1LA pins_1RB0LD_1LC1RB_0RB1LA_0RC1LA Cc 1).
