(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0LD_1LC1RB_0RB1LD_0RA0LC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z0_1RB0LD_1LC1RB_0RB1LD_0RA0LC /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_1RB0LD_1LC1RB_0RB1LD_0RA0LC = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB0LD_1LC1RB_0RB1LD_0RA0LC, cden, Z0_1RB0LD_1LC1RB_0RB1LD_0RA0LC, Z1_1RB0LD_1LC1RB_0RB1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB0LD_1LC1RB_0RB1LD_0RA0LC : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P0_1RB0LD_1LC1RB_0RB1LD_0RA0LC /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P1_1RB0LD_1LC1RB_0RB1LD_0RA0LC = Cc (Pos.succ p).
Proof.
