(** ** The certificate *)

Definition A0_1RB0LD_1LC1RB_1RB1LD_0RA0LC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1] [] 0 0 []).
Definition A1_1RB0LD_1LC1RB_1RB1LD_0RA0LC : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1;S0] [] 0 0 []).
Definition chi_1RB0LD_1LC1RB_1RB1LD_0RA0LC : list lstep := [SWin 1; SWinR 5; SCycL 2 0; SWin 4; SCycR 2; SWin 6].

Lemma run_int_1RB0LD_1LC1RB_1RB1LD_0RA0LC : srun tm false true chi_1RB0LD_1LC1RB_1RB1LD_0RA0LC A0_1RB0LD_1LC1RB_1RB1LD_0RA0LC = Some (A1_1RB0LD_1LC1RB_1RB1LD_0RA0LC, 4, 16).
