      with (l := [SWin 4]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0LD_1LC1RC_0RB1LD_0LC1LA
      with (l := [SWin 8]).
    vm_compute; reflexivity.
  - (* B0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_1LC1RC_0RB1LD_0LC1LA (StB, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_1LC1RC_0RB1LD_0LC1LA [SWin 8; SCycL 2 0; SWin 2; SWinL 3] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0LD_1LC1RC_0RB1LD_0LC1LA
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0LD_1LC1RC_0RB1LD_0LC1LA
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LD_1LC1RC_0RB1LD_0LC1LA
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_1LC1RC_0RB1LD_0LC1LA (StD, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_1LC1RC_0RB1LD_0LC1LA [SWin 8; SCycL 2 0; SWin 2; SWinL 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LD_1LC1RC_0RB1LD_0LC1LA
      with (l := [SWin 3]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB0LD_1LC1RC_0RB1LD_0LC1LA : NeverQuasiHaltsTr tm_1RB0LD_1LC1RC_0RB1LD_0LC1LA.
