Lemma gen_1RB0LD_1LC1RC_1LA0RB_1LA0RD : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_1RB0LD_1LC1RC_1LA0RB_1LA0RD) = lift (Cin (Pos.succ v)).
