Lemma gsi_1RB0LD_1RC0LD_1LD1RB_0RA1LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB0LD_1RC0LD_1LD1RB_0RA1LD.
