Lemma gsi_1RB0LD_1RC0RB_0LA0RB_1RB1LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB0LD_1RC0RB_0LA0RB_1RB1LA.
