Qed.

Lemma lbl_1RB0LD_1RC0RB_0LA0RB_1RB1LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LD_1RC0RB_0LA0RB_1RB1LA : forall p j, cview p = (S j, None) ->
