               run_boot_1RB0LD_1RC0RB_0LA0RB_1RB1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB0LD_1RC0RB_0LA0RB_1RB1LA p (pow2 j) (pow2 j));
        [exact HB1|].
