(** ** The lap *)

Lemma lap_1RB0LD_1RC0RB_0LA0RB_1RB1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
