Lemma gei_1RB0LD_1RC0RB_0LA1LB_1LA1LD : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_00_01_0 q0 ++ [S0;S1;S0]) [] j A1_1RB0LD_1RC0RB_0LA1LB_1LA1LD) = lift (Cc (Pos.succ p)).
