Lemma gsi_1RB0LD_1RC0RB_1LA0LB_0LD0RC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j A0_1RB0LD_1RC0RB_1LA0LB_0LD0RC.
