      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0LD_1RC0RB_1LA0LB_0LD0RC
      with (l := [SWin 1; SWin 2; SCycL 3 0; SWin 2; SRotR 1; SWin 1]).
