    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_1RC0RB_1LA1LB_0LD0RC (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_1RC0RB_1LA1LB_0LD0RC [SWin 4; SCycL 4 0; SWin 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1RC0RB_1LA1LB_0LD0RC [SWinR 2; SCycL 4 0; SWin 4] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1RC0RB_1LA1LB_0LD0RC [SWinR 2; SCycL 4 0; SWin 4; SCycR 2; SWin 1] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

