(** 1RB0LD_1RC0RC_0LA0RB_0RC1LA *)
Definition tm_1RB0LD_1RC0RC_0LA0RB_0RC1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StD
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S0 DR StC
  | StC, S0 => mk S0 DL StA | StC, S1 => mk S0 DR StB
