(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LD_1RC0RC_0LA0RB_1RB1LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB0LD_1RC0RC_0LA0RB_1RB1LA.
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (H1 & _).
  unfold Cc_1RB0LD_1RC0RC_0LA0RB_1RB1LA, cden, A0_1RB0LD_1RC0RC_0LA0RB_1RB1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB0LD_1RC0RC_0LA0RB_1RB1LA : forall p j q0, cview p = (j, Some q0) ->
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_1RB0LD_1RC0RC_0LA0RB_1RB1LA = Cc (Pos.succ p).
