Lemma geo_1RB0LD_1RC0RC_0LA0RB_1RB1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LD_1RC0RC_0LA0RB_1RB1LA) = lift (Cc (Pos.succ p)).
