Lemma geo_1RB0LD_1RC0RC_0LA0RC_1LA0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LD_1RC0RC_0LA0RC_1LA0RB) = lift (Cc (Pos.succ p)).
