(** ** Bootstrap *)

Lemma boot_1RB0LD_1RC0RC_0LA0RC_1LA0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 14.
  assert (H : match csteps tm 14 c0 with
