    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LD_1RC0RC_0LA0RC_1LA0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LD_1RC0RC_0LA0RC_1LA0RB = Some t ->
