(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB0LD_1RC0RC_0LA1RB_1RC1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB0LD_1RC0RC_0LA1RB_1RC1LD. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LD_1RC0RC_0LA1RB_1RC1LD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LD_1RC0RC_0LA1RB_1RC1LD p (pow2 j)).
  - exists (4 * j + 9), (cden [] [] j BB1_1RB0LD_1RC0RC_0LA1RB_1RC1LD).
    split; [lia|]. split; [| exact (gbo_1RB0LD_1RC0RC_0LA1RB_1RC1LD j)].
    rewrite (gso_1RB0LD_1RC0RC_0LA1RB_1RC1LD p j E).
    exact (srun_sound tm true true chb_1RB0LD_1RC0RC_0LA1RB_1RC1LD B0_1RB0LD_1RC0RC_0LA1RB_1RC1LD BB1_1RB0LD_1RC0RC_0LA1RB_1RC1LD 4 9
             run_boot_1RB0LD_1RC0RC_0LA1RB_1RC1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 11), (cden [] [] j B1_1RB0LD_1RC0RC_0LA1RB_1RC1LD).
    split; [| exact (geo_1RB0LD_1RC0RC_0LA1RB_1RC1LD p j E)].
    rewrite (gxi_1RB0LD_1RC0RC_0LA1RB_1RC1LD j).
    exact (srun_sound tm true true che_1RB0LD_1RC0RC_0LA1RB_1RC1LD BE0_1RB0LD_1RC0RC_0LA1RB_1RC1LD B1_1RB0LD_1RC0RC_0LA1RB_1RC1LD 4 11
             run_exit_1RB0LD_1RC0RC_0LA1RB_1RC1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0LD_1RC0RC_0LA1RB_1RC1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LD_1RC0RC_0LA1RB_1RC1LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LD_1RC0RC_0LA1RB_1RC1LD p j' E).
