    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LD_1RC1LA_0LA1RB_1LC0RB
      with (l := [SRotL 1; SWin 1; SCycL 4 0; SWin 1; SWinL 3]).
    vm_compute; reflexivity.
