(** ** The lap *)

Lemma lap_1RB0LD_1RC1LA_1LD1RC_0RB1LB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
