  - destruct (lapi_1RB0LD_1RC1LA_1LD1RC_0RB1LB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_1RC1LA_1LD1RC_0RB1LB B0_1RB0LD_1RC1LA_1LD1RC_0RB1LB B1_1RB0LD_1RC1LA_1LD1RC_0RB1LB 6 24 p j' [] []).
    + exact run_ovf_1RB0LD_1RC1LA_1LD1RC_0RB1LB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_1RC1LA_1LD1RC_0RB1LB p j' E).
    + exact (geo_1RB0LD_1RC1LA_1LD1RC_0RB1LB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LD_1RC1LA_1LD1RC_0RB1LB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
