Lemma geo_1RB0LD_1RC1LD_0LA0RC_1LB1LB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LD_1RC1LD_0LA0RC_1LB1LB) = lift (Cc (Pos.succ p)).
